# Writes the hedra command files of the bubble loft: loft.txt (the greenhouse loft: plank floor, the big
# window's frame and its brass sill (the danger line), the planter, the side glass walls with shelves,
# pots, plants, a hanging basket and a crate of spare orbs), far.txt (the rooftops and the low sun seen
# through the glass), beam.txt (the hanging rafter the orbs cling to, on two ropes: a game bone) and
# orb_dusk/rose/ember/sun.txt (one faceted glass orb per colour: the pools).
# Run from models/env: /usr/bin/python3 make_env.py
# hedra: up Z, front -Y (the camera side). The game's plane is hedra y = 0 (glTF z = 0). Colours are exact
# Sunset 8 steps (sRGB 0..1). The layout numbers are shared with scene/game.as.
import math, random

HEX = {"navy": "464678", "plum": "9a6390", "pink": "e67595", "salmon": "ff8b6f", "orange": "ffa936",
       "gold": "ffc247", "yellow": "ffd647", "cream": "ffff78"}
def rgb(h):
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.3f}" for i in (0, 2, 4))
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {rgb(HEX[col])} --no-slot"
    return s + (f" --emission {rgb(HEX[col])}" if emit else "")
def box(name, x0, x1, y0, y1, z0, z1, m):
    return [f"add mesh cube --name {name} --size 1 --location {(x0 + x1) / 2:.4f} {(y0 + y1) / 2:.4f} {(z0 + z1) / 2:.4f}",
            f"scale {x1 - x0:.4f} {y1 - y0:.4f} {z1 - z0:.4f}", "apply --scale", f"material assign {m}"]
def disc(name, x, y, z, r, depth, n, m, spin=0.0):
    """a cylinder whose axis looks at the camera (hedra Y)"""
    return [f"add mesh cylinder --name {name} --vertices {n} --radius {r:.4f} --depth {depth:.4f} "
            f"--location {x:.4f} {y:.4f} {z:.4f} --rotation 90 {spin:.2f} 0", f"material assign {m}"]
def pot(name, x, y, z, r, h, m="Clay"):
    """a tapered octagonal flower pot standing at z, rim r"""
    return [f"add mesh cone --name {name} --vertices 8 --radius1 {r * 0.72:.4f} --radius2 {r:.4f} --depth {h:.4f} "
            f"--location {x:.4f} {y:.4f} {z + h / 2:.4f} --rotation 0 0 22.5", f"material assign {m}",
            f"add mesh cylinder --name {name}Rim --vertices 8 --radius {r * 1.08:.4f} --depth {h * 0.22:.4f} "
            f"--location {x:.4f} {y:.4f} {z + h * 0.92:.4f} --rotation 0 0 22.5", f"material assign {m}"]
def blob(name, x, y, z, r, sx=1.0, sy=1.0, sz=1.0, m="Leaf", sub=1):
    return [f"add mesh ico-sphere --name {name} --subdivisions {sub} --radius {r:.4f} --location {x:.4f} {y:.4f} {z:.4f}",
            f"scale {sx:.3f} {sy:.3f} {sz:.3f}", "apply --scale", f"material assign {m}"]
def write(fn, lines):
    open(fn, "w").write("\n".join(lines) + "\n")

# ---------------------------------------------------------------- layout (glTF metres, shared with game.as)
FIELD_X = 3.68          # the window's inner half width: the walls the orbs bounce off
R = 0.46                # orb radius (a cell); the orb model is smaller (ORB_R) so the sky shows between orbs
ORB_R = 0.40
BEAM_Z = 9.75           # the rafter's underside at rest
SILL_Z = 3.08           # the brass sill: the danger line
POST = 0.37

if __name__ == "__main__":
    rnd = random.Random(8)
    # ------------------------------------------------------------ loft
    L = ["# The rooftop greenhouse loft at sunset (generated by make_env.py).", "new",
         mat("Wood", "salmon"), mat("WoodDark", "plum"), mat("Frame", "orange"), mat("Iron", "navy"),
         mat("Brass", "gold"), mat("Clay", "salmon"), mat("Leaf", "plum"), mat("Panel", "plum"),
         mat("Dusk", "navy"), mat("Rose", "pink"), mat("Ember", "orange"), mat("Sprout", "pink")]
    # plank floor: five planks along x, alternating
    for i in range(5):
        y0 = -2.0 + 0.58 * i
        L += box(f"Plank{i}", -9.0, 9.0, y0, y0 + 0.58, -0.25, 0.0, "Wood" if i % 2 == 0 else "WoodDark")
    # the big window: two posts (the walls), the transom, the brass sill across it
    for s, nm in ((-1, "L"), (1, "R")):
        x0, x1 = (-FIELD_X - POST, -FIELD_X) if s < 0 else (FIELD_X, FIELD_X + POST)
        L += box("Post" + nm, x0, x1, -0.3, 0.5, 0.0, 11.4, "Frame")
        L += box("Foot" + nm, x0 - 0.08, x1 + 0.08, -0.38, 0.55, 0.0, 0.35, "WoodDark")
    L += box("Transom", -FIELD_X - POST, FIELD_X + POST, -0.3, 0.5, 10.45, 11.4, "WoodDark")
    L += box("Sill", -FIELD_X, FIELD_X, 0.45, 0.62, SILL_Z, SILL_Z + 0.12, "Brass")
    for i, x in enumerate((-2.4, 0.0, 2.4)):
        L += box(f"SillPin{i}", x - 0.07, x + 0.07, 0.5, 0.62, SILL_Z - 0.18, SILL_Z, "Brass")
    # the planter trough behind the puffer, seedlings in it
    L += box("Planter", -FIELD_X, FIELD_X, 0.75, 1.35, 0.0, 0.62, "Iron")
    L += box("PlanterLip", -FIELD_X, FIELD_X, 0.68, 1.4, 0.62, 0.72, "Wood")
    for i in range(9):
        x = -3.3 + 0.82 * i + rnd.uniform(-0.12, 0.12)
        L += blob(f"Sprout{i}", x, 1.05, 0.82, 0.2 + rnd.uniform(0, 0.06), 1.0, 0.8, 0.9, m="Sprout")
    # side walls: a plum knee wall, a ledge, and the glass's iron mullions over the sky
    for s, nm in ((-1, "L"), (1, "R")):
        xa, xb = sorted((s * (FIELD_X + POST), s * 9.0))
        L += box("Knee" + nm, xa, xb, 0.6, 0.9, 0.0, 1.3, "Panel")
        L += box("Ledge" + nm, xa, xb, 0.3, 0.95, 1.3, 1.42, "Wood")
        for k, x in enumerate((5.45, 6.85, 8.25)):
            L += box(f"Mull{nm}{k}", s * x - 0.07, s * x + 0.07, 0.7, 0.84, 1.42, 11.4, "Iron")
        for k, z in enumerate((4.4, 7.4)):
            L += box(f"Bar{nm}{k}", xa, xb, 0.7, 0.84, z - 0.06, z + 0.06, "Iron")
        L += box("Head" + nm, xa, xb, 0.5, 0.9, 10.45, 11.4, "Frame")
    # left: a big potted fern on the floor, a shelf with two pots, a high shelf with a trailing vine
    L += pot("FloorPot", -7.45, 0.0, 0.0, 0.5, 0.95)
    for i, (dx, dz, r, sx, sz) in enumerate(((0.0, 1.55, 0.55, 1.0, 1.25), (-0.45, 1.25, 0.42, 1.1, 0.9),
                                            (0.45, 1.3, 0.42, 1.0, 1.0), (-0.2, 2.15, 0.36, 0.9, 1.1), (0.3, 2.0, 0.32, 1.0, 1.0))):
        L += blob(f"Fern{i}", -7.45 + dx, -0.05, dz, r, sx, 0.8, sz)
    L += box("Shelf1", -6.6, -4.4, -0.45, 0.45, 2.6, 2.72, "Wood")
    for i, x in enumerate((-6.3, -4.7)):
        L += box(f"Brk1{i}", x - 0.06, x + 0.06, 0.2, 0.45, 2.2, 2.6, "WoodDark")
    L += pot("PotA", -5.95, 0.0, 2.72, 0.32, 0.55)
    L += blob("BushA", -5.95, 0.0, 3.6, 0.42, 1.1, 0.85, 1.0)
    L += blob("BushA2", -6.25, -0.05, 3.35, 0.28)
    L += pot("PotB", -4.95, 0.0, 2.72, 0.26, 0.45)
    for i in range(4):
        a = math.radians(-35 + 25 * i)
        L += [f"add mesh cone --name Spike{i} --vertices 4 --radius1 0.12 --radius2 0 --depth 0.75 --location 0 0 0.375",
              f"set rotation 0 {math.degrees(a):.1f} 0", "apply --rotation",
              f"translate -4.95 0 3.12", "apply --location", "material assign Leaf"]
    L += box("Shelf2", -7.0, -4.5, -0.45, 0.45, 5.7, 5.82, "Wood")
    for i, x in enumerate((-6.7, -4.8)):
        L += box(f"Brk2{i}", x - 0.06, x + 0.06, 0.2, 0.45, 5.3, 5.7, "WoodDark")
    L += pot("PotC", -5.6, 0.0, 5.82, 0.34, 0.5)
    L += blob("VineTop", -5.6, 0.0, 6.5, 0.36, 1.2, 0.8, 0.8)
    for i, (x, n) in enumerate(((-5.95, 4), (-5.35, 5), (-6.25, 3))):
        for k in range(n):
            L += blob(f"Vine{i}_{k}", x + 0.06 * (k % 2), -0.3, 6.15 - 0.36 * k, 0.17)
    # right: a shelf with pots, a hanging basket, a crate of spare orbs on the floor
    L += box("Shelf3", 4.4, 7.4, -0.45, 0.45, 3.1, 3.22, "Wood")
    for i, x in enumerate((4.7, 7.1)):
        L += box(f"Brk3{i}", x - 0.06, x + 0.06, 0.2, 0.45, 2.7, 3.1, "WoodDark")
    L += pot("PotD", 5.0, 0.0, 3.22, 0.3, 0.5)
    for i, (dx, dz, r) in enumerate(((0.0, 4.05, 0.38), (-0.3, 3.9, 0.26), (0.3, 3.95, 0.28))):
        L += blob(f"BushD{i}", 5.0 + dx, 0.0, dz, r)
    L += pot("PotE", 6.55, 0.0, 3.22, 0.36, 0.6)
    for i in range(5):
        a = math.radians(-50 + 25 * i)
        L += [f"add mesh cone --name Frond{i} --vertices 4 --radius1 0.16 --radius2 0 --depth 1.0 --location 0 0 0.5",
              "scale 1 0.5 1", "apply --scale",
              f"set rotation 0 {math.degrees(a):.1f} 0", "apply --rotation",
              f"translate 6.55 0 3.7", "apply --location", "material assign Leaf"]
    L += box("Rope", 6.15, 6.23, 0.2, 0.28, 7.7, 10.45, "WoodDark")
    L += [f"add mesh cone --name Basket --vertices 8 --radius1 0.32 --radius2 0.5 --depth 0.45 --location 6.19 0.24 7.45 --rotation 0 0 22.5",
          "material assign Clay"]
    for i, (dx, dz, r) in enumerate(((0.0, 7.75, 0.4), (-0.42, 7.5, 0.26), (0.42, 7.55, 0.27))):
        L += blob(f"Fluff{i}", 6.19 + dx, 0.2, dz, r)
    for i, (dx, n) in enumerate(((-0.35, 4), (0.3, 3), (0.0, 2))):
        for k in range(n):
            L += blob(f"Trail{i}_{k}", 6.19 + dx, -0.1, 7.15 - 0.34 * k, 0.16)
    L += box("Crate", 5.3, 6.9, -0.6, 0.3, 0.0, 0.85, "Wood")
    L += box("CrateBand", 5.25, 6.95, -0.66, 0.36, 0.55, 0.68, "WoodDark")
    for i, (x, m) in enumerate(((5.62, "Dusk"), (6.15, "Rose"), (6.62, "Ember"))):
        L += blob(f"Spare{i}", x, -0.15, 0.95 + (0.06 if i == 1 else 0), 0.3, m=m, sub=2)
    L += ["select all", "shade flat", "export loft.glb"]
    write("loft.txt", L)

    # ------------------------------------------------------------ far: rooftops and the low sun
    F = ["# What the glass shows: rooftops in the dusk, chimneys, a water tank and the low sun (make_env.py).",
         "new", mat("Roof", "navy"), mat("Sun", "yellow", True), mat("Cloud", "salmon", True)]
    houses = [(-11.0, -7.6, 0.4), (-7.6, -5.4, 0.8), (-5.4, -3.0, 0.2), (-3.0, -1.1, 0.55), (-1.1, 1.3, 0.15),
              (1.3, 3.1, 0.7), (3.1, 5.6, 0.25), (5.6, 8.0, 0.65), (8.0, 11.0, 0.3)]
    for i, (x0, x1, h) in enumerate(houses):
        y0 = 10.0 + (i % 3) * 0.6
        F += box(f"House{i}", x0, x1, y0, y0 + 2.0, 0.0, h, "Roof")
        # lit windows: warm squares on the front walls
        for k in range(int((x1 - x0) / 0.9)):
            wx = x0 + 0.45 + 0.9 * k
            if (i * 3 + k) % 3 != 1 and h >= 0.4:
                F += box(f"Win{i}_{k}", wx - 0.12, wx + 0.12, y0 - 0.06, y0, h - 0.34, h - 0.1, "Sun")
        if i % 2 == 0:
            cx = x0 + (x1 - x0) * (0.3 if i % 4 == 0 else 0.7)
            F += box(f"Chim{i}", cx - 0.17, cx + 0.17, y0 + 0.3, y0 + 0.64, h, h + 0.55, "Roof")
        if i in (1, 5):
            # a pitched roof: a long prism along x
            F += [f"add mesh cylinder --name Gable{i} --vertices 3 --radius 0.45 --depth {x1 - x0:.3f} "
                  f"--location {(x0 + x1) / 2:.3f} {y0 + 1.0:.3f} {h + 0.1:.3f} --rotation 0 90 0", "material assign Roof"]
    # a water tank on legs on a roof right of the middle
    F += box("TankLegs", 3.9, 4.9, 10.9, 11.3, 0.25, 0.7, "Roof")
    F += [f"add mesh cylinder --name Tank --vertices 8 --radius 0.55 --depth 0.8 --location 4.4 11.1 1.1 --rotation 0 0 22.5",
          "material assign Roof",
          f"add mesh cone --name TankTop --vertices 8 --radius1 0.62 --radius2 0.05 --depth 0.35 --location 4.4 11.1 1.67 --rotation 0 0 22.5",
          "material assign Roof"]
    F += disc("SunDisc", -2.3, 13.5, 0.75, 1.2, 0.2, 16, "Sun", 11.25)
    # cloud streaks over the side panes only (behind the mullions)
    for i, (x0, x1, z) in enumerate(((-9.5, -6.2, 6.0), (-8.8, -5.0, 8.6), (5.0, 8.4, 7.0), (5.6, 9.5, 5.2), (-8.0, -5.6, 3.9))):
        F += box(f"Cloud{i}", x0, x1, 14.0, 14.1, z, z + 0.22, "Cloud")
    F += ["select all", "shade flat", "export far.glb"]
    write("far.txt", F)

    # ------------------------------------------------------------ the rafter (a game bone): origin at its underside
    B = ["# The hanging rafter the orbs cling to, with brass bands and two ropes rising out of the frame.",
         "# Origin at the middle of its underside (the game lowers it a row at a time). make_env.py.",
         "new", mat("Wood", "orange"), mat("Brass", "gold"), mat("Rope", "salmon")]
    B += box("Beam", -FIELD_X + 0.04, FIELD_X - 0.04, -0.3, 0.3, 0.0, 0.45, "Wood")
    for i, x in enumerate((-3.0, -1.0, 1.0, 3.0)):
        B += box(f"Band{i}", x - 0.09, x + 0.09, -0.35, 0.35, -0.05, 0.5, "Brass")
    for i, x in enumerate((-2.6, 2.6)):
        B += box(f"Rope{i}", x - 0.06, x + 0.06, -0.06, 0.06, 0.45, 7.6, "Rope")
    B += ["select all", "shade flat", "export beam.glb"]
    write("beam.txt", B)

    # ------------------------------------------------------------ the orbs: faceted glass, one file per colour
    for name, col in (("dusk", "navy"), ("rose", "pink"), ("ember", "orange"), ("sun", "cream")):
        write(f"orb_{name}.txt", [f"# A {name} glass orb, r {ORB_R} (in a {R} cell), a faceted 80-face ball; origin at its centre. make_env.py.",
            "new", mat("Glass", col),
            f"add mesh ico-sphere --name Orb --subdivisions 2 --radius {ORB_R}", "material assign Glass",
            "shade flat", f"export orb_{name}.glb"])
